def example_for(question):
    text = question["q"].casefold()
    for key, example in EXAMPLES:
        if key in text:
            return "Por ejemplo: " + example
    return "Para recordarlo en la práctica: " + question["corr"] + ". Si tienes dudas sobre tu situación, consulta al personal de salud."


def test_risk(score):
    if not isinstance(score, int) or not 0 <= score <= 10:
        raise ValueError("La nota debe estar entre 0 y 10")
    return "Riesgo educativo alto" if score <= 6 else "Riesgo educativo leve" if score <= 8 else "Sin riesgo educativo"


def final_parts(rows, score, risk):
    sections = [f"Has terminado la evaluación. Obtuviste {score} aciertos de 10. {risk}.",
                "Esta clasificación mide aprendizaje, no diagnostica ni descarta problemas de salud.",
                "Vamos a repasar todas las preguntas, con especial atención a las que se confundieron."]
    for number, row in enumerate(rows, 1):
        sections.extend([f"Pregunta {number}.", row['question'],
                         "Acertaste." if row["correct"] else f"Aquí hubo una confusión. Elegiste: {row['selected']}.",
                         f"La respuesta correcta es: {row['answer']}.", row["feedback"], row.get("example", "")])
    sections.append("Puedes volver a escuchar esta explicación y revisar las tarjetas de autoeducación. Gracias por aprender a cuidarte.")
    return [part for part in sections if part]


def final_narration(rows, score, risk):
    return " ".join(final_parts(rows, score, risk))
